{
  "lecture": [
    {
      "etiquette": "F16",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle en fin de course augmente d'au moins 20 %, sans augmentation des fausses promotions."
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle : nombre de composantes plantées couvertes (D2) et taux de fausses découvertes à coût égal"
      },
      "R3": {
        "valeur": 1,
        "passage": "Insérer cette table de comptage purement descriptive dans la vue publique à côté de la liste complète des lois de l'archive, sans aucune consigne prescriptive, ni quota, ni score."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "pour chaque paire (t_i, t_j), le nombre de lois où t_i apparaît dans une condition (`si_sinon` ou `par_sous_population`) et t_j dans la branche prédite."
      },
      "R6": {
        "valeur": 1,
        "passage": "vérifier par l'oracle sur les cartes brutes si de nouvelles composantes plantées sont touchées (coût : quelques dollars d'appels)."
      },
      "R7": {
        "valeur": 0,
        "motif": "La table décrit les usages syntaxiques sans expliquer pourquoi les proposeurs privilégieraient les couples absents plutôt que les couples fréquents, ni pourquoi cela augmenterait la couverture vraie."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F17",
      "R1": {
        "valeur": 1,
        "passage": "La couverture des composantes vraies ne baisse pas de plus de 5 % en relatif, à tirages frais égaux."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : copies promues, composantes vraies couvertes, composantes conditionnelles absorbées. Coût : heures de processeur du juge, la classe étant plus grande."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le dénominateur est le maximum de vraisemblance sur la classe élargie. Le reste du juge est inchangé. La preuve de validité est scellée avant toute course."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche affirme que la garantie se conserve avec le nul élargi, mais ne nomme ni la borne d'espérance des valeurs e, ni le contrôle des comparaisons multiples, ni une garantie équivalente."
      },
      "R5": {
        "valeur": 1,
        "passage": "La classe du nul reçoit, pour chaque paire de lois prises parmi l'archive et les lois aveugles, chaque trait public et chaque décile public, la loi par morceaux de profondeur 1."
      },
      "R6": {
        "valeur": 1,
        "passage": "Quelques heures de processeur. Aucun appel de modèle."
      },
      "R7": {
        "valeur": 1,
        "passage": "Le mécanisme répond à la limite connue du juge, qui cède hors de la classe de son nul : la garde contre les copies est fermée à l'endroit exact où une pression vers la variété fait passer des copies."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F18",
      "R1": {
        "valeur": 1,
        "passage": "couverture égale à une composante près sur les 24 mondes, coût par génération réduit d'au moins 40 %, le nombre de lois fausses et de copies promues ne montant pas"
      },
      "R2": {
        "valeur": 1,
        "passage": "ce que l'oracle dit des composantes couvertes et des lois fausses ou copiées promues, et ce que les relais relèvent en dollars et en jetons"
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucun autre réglage n'est touché, et aucun agent ne voit de verdict."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "Le retour à la valeur actuelle lorsqu'une génération ne produit aucune carte valide n'est pas concilié avec la valeur figée au départ, et son moment d'application n'est pas précisé."
      },
      "R6": {
        "valeur": 1,
        "passage": "de l'ordre de 115 USD sur l'ensemble ; un premier passage de 5 mondes, vers 25 USD, dit si le signe tient"
      },
      "R7": {
        "valeur": 0,
        "motif": "Aucun lien n'est donné entre la réduction des exemples et la puissance du juge inchangé, ni entre cette puissance et une baisse de coût de 40 % à couverture presque constante."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F19",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, le nombre de composantes plantées distinctes touchées par les propositions brutes augmente d'au moins 30 % en relatif par monde et par génération."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes couvertes aux trois étages, lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "La seule information échangée est le texte des pairs, jamais un verdict. Le regroupement des doublons, déjà mécanique, donne au rappel un contenu factuel plutôt qu'une prime."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "Le proposeur de rang k reçoit, en session neuve, la vue habituelle plus une section qui contient : les cartes extraites des réponses brutes scellées des rangs 1 à k−1, sans tri et sans mention du gardien"
      },
      "R6": {
        "valeur": 1,
        "passage": "20 mondes, 3 bras (témoin, chaîne, placebo), 2 générations, 4 proposeurs, environ 480 appels, soit quelques centaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un proposeur qui voit qu'un constat est déjà proposé, avec le rappel factuel qu'une carte reprenant une carte déjà proposée sera regroupée avec elle, porte ses cartes ailleurs."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F20",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes (D2 sur les retenues) augmente d'au moins 30 % par rapport à l'architecture à passe unique, sans hausse des promotions de lois fausses."
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (composantes plantées couvertes D2, fausses promotions) et coût total (dollars d'appels par rôle et heures de calcul local) par génération."
      },
      "R3": {
        "valeur": 0,
        "motif": "La maximisation de la distance numérique de Jaccard sert de prime de variété dans la sélection des cibles, sans nommer cette objection ni expliquer pourquoi elle ne s'appliquerait pas."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "La distance mutuelle à maximiser n'a pas d'agrégation définie, et ni les ex æquo ni le cas de moins de six tuples admissibles ne sont réglés."
      },
      "R6": {
        "valeur": 0,
        "motif": "L'expérience a un coût annoncé et un appel standard comme comparaison, mais aucun contrôle négatif ni témoin explicitement à coût égal."
      },
      "R7": {
        "valeur": 0,
        "motif": "La séparation des rôles et la dispersion syntaxique des tuples n'expliquent ni pourquoi davantage de composantes vraies seraient couvertes, ni pourquoi l'ajout d'une passe réduirait le coût total."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
